template.script:
(function () {
    var zip = document.getElementById('visar_addr_zip');
    var city = document.getElementById('visar_addr_city');
    var state = document.getElementById('visar_addr_state');
    var feedback = document.getElementById('visar_cp_feedback');
    if (!zip) { return; }
    function lookup() {
        var cp = (zip.value || '').replace(/\D/g, '').slice(0, 5);
        if (cp.length !== 5) {
            if (feedback) { feedback.textContent = ''; }
            return;
        }
        fetch('/appointment/visar/cp-info?cp=' + encodeURIComponent(cp), {
            headers: {'X-Requested-With': 'XMLHttpRequest'},
        }).then(function (r) { return r.json(); }).then(function (data) {
            if (data && data.found) {
                if (city) { city.value = data.municipality || ''; }
                if (state) { state.value = data.state || 'Nuevo León'; }
                if (feedback) {
                    feedback.className = 'form-text mt-2 text-success';
                    feedback.textContent = 'Zona detectada: ' + (data.zone_name || '');
                }
            } else {
                if (city) { city.value = ''; }
                if (feedback) {
                    feedback.className = 'form-text mt-2 text-danger';
                    feedback.textContent =
                        'No damos servicio en este código postal. Contáctanos.';
                }
            }
        }).catch(function () {});
    }
    zip.addEventListener('change', lookup);
    zip.addEventListener('blur', lookup);
    if (zip.value) { lookup(); }
})();

div.script:
(function () {
    var form = document.getElementById('visar_interior_form');
    if (!form) { return; }
    var sabe = document.getElementById('visar_interior_sabe');
    var estima = document.getElementById('visar_interior_estima');
    function toggle() {
        var checked = form.querySelector('input[name="interior_mode"]:checked');
        var isSabe = checked && checked.value === 'sabe';
        sabe.style.display = isSabe ? 'block' : 'none';
        estima.style.display = isSabe ? 'none' : 'block';
    }
    form.querySelectorAll('input[name="interior_mode"]').forEach(function (el) {
        el.addEventListener('change', toggle);
    });
    toggle();
})();

(function () {
    var form = document.getElementById('visar_exterior_form');
    if (!form) { return; }
    var sabe = document.getElementById('visar_exterior_sabe');
    var estima = document.getElementById('visar_exterior_estima');
    function toggle() {
        var checked = form.querySelector('input[name="exterior_mode"]:checked');
        var isSabe = checked && checked.value === 'sabe';
        sabe.style.display = isSabe ? 'block' : 'none';
        estima.style.display = isSabe ? 'none' : 'block';
    }
    form.querySelectorAll('input[name="exterior_mode"]').forEach(function (el) {
        el.addEventListener('change', toggle);
    });
    toggle();
})();

(function () {
    var form = document.getElementById('visar_extras_form');
    var totalEl = document.getElementById('visar_extras_total');
    if (!form || !totalEl) { return; }
    var base = parseFloat(totalEl.dataset.base) || 0;
    var sym = totalEl.dataset.symbol || '';
    var boxes = form.querySelectorAll('input[name="extra_ids"]');
    function fmt(n) {
        return sym + n.toLocaleString(undefined,
            {minimumFractionDigits: 2, maximumFractionDigits: 2});
    }
    function recompute() {
        var t = base;
        boxes.forEach(function (b) {
            if (b.checked) { t += parseFloat(b.dataset.subtotal) || 0; }
        });
        totalEl.textContent = fmt(t);
    }
    boxes.forEach(function (b) { b.addEventListener('change', recompute); });
    recompute();
})();
